import { getModels, getProviders, type Api, type Model } from "@earendil-works/pi-ai/compat";
import { getAppStorage, type CustomProvider } from "@earendil-works/pi-web-ui";
import { proxiedProviderRequestUrl } from "./provider-proxy";
import {
	getNotOrganicAccount,
	isNotOrganicFeatureEnabled,
	NOTORGANIC_DEFAULT_MODEL,
	NOTORGANIC_PROVIDER_ID,
} from "../notorganic-provider";
import { getOAuthAccessToken, providerToOAuthId } from "../keating/oauth";
import { withApiRetry } from "../keating/api-retry";

export type KeatingCustomProviderType =
	| "ollama"
	| "llama.cpp"
	| "vllm"
	| "lmstudio"
	| "gateway"
	| "openai-completions"
	| "openai-responses"
	| "anthropic-messages"
	| "synthetic";

export type KeatingGatewayKind = "bifrost" | "plexus" | "litellm" | "generic";

export type KeatingCustomProvider = Omit<CustomProvider, "type"> & {
	type: KeatingCustomProviderType;
	gatewayKind?: KeatingGatewayKind;
};

const AUTO_DISCOVERY_TYPES = new Set<KeatingCustomProviderType>(["ollama", "llama.cpp", "vllm", "lmstudio"]);
const OPENAI_COMPATIBLE_TYPES = new Set<KeatingCustomProviderType>([
	"gateway",
	"openai-completions",
	"openai-responses",
	"synthetic",
]);

function trimTrailingSlash(value: string): string {
	return value.replace(/\/+$/, "");
}

function modelCost() {
	return {
		input: 0,
		output: 0,
		cacheRead: 0,
		cacheWrite: 0,
	};
}

function toContextWindow(value: unknown, fallback = 0): number {
	if (typeof value === "number" && Number.isFinite(value)) return value;
	if (typeof value === "string") {
		const parsed = Number.parseInt(value, 10);
		if (Number.isFinite(parsed)) return parsed;
	}
	return fallback;
}

function inferInputModes(model: any): Array<"text" | "image"> {
	const supported = new Set<string>();

	if (Array.isArray(model?.input)) {
		for (const entry of model.input) {
			if (entry === "image" || entry === "text") supported.add(entry);
		}
	}

	if (Array.isArray(model?.input_modalities)) {
		for (const entry of model.input_modalities) {
			if (entry === "image" || entry === "text") supported.add(entry);
		}
	}

	if (Array.isArray(model?.modalities)) {
		for (const entry of model.modalities) {
			if (entry === "image" || entry === "text") supported.add(entry);
		}
	}

	if (model?.vision === true) supported.add("image");
	if (supported.size === 0) supported.add("text");

	return Array.from(supported) as Array<"text" | "image">;
}

function inferReasoning(model: any): boolean {
	if (typeof model?.reasoning === "boolean") return model.reasoning;
	if (typeof model?.supports_reasoning === "boolean") return model.supports_reasoning;
	if (Array.isArray(model?.capabilities)) return model.capabilities.includes("thinking");
	const name = String(model?.id ?? model?.name ?? "").toLowerCase();
	return name.includes("thinking") || name.includes("reasoning");
}

function manualProviderApi(type: KeatingCustomProviderType): Api {
	switch (type) {
		case "openai-responses":
			return "openai-responses" as Api;
		case "anthropic-messages":
			return "anthropic-messages" as Api;
		case "synthetic":
		case "openai-completions":
		default:
			return "openai-completions" as Api;
	}
}

function openAiCompatibleBaseUrls(provider: KeatingCustomProvider): string[] {
	const baseUrl = trimTrailingSlash(provider.baseUrl);
	if (baseUrl.endsWith("/v1")) return [baseUrl];

	if (provider.type === "gateway" && provider.gatewayKind === "bifrost") {
		return [`${baseUrl}/v1`, `${baseUrl}/openai/v1`, baseUrl];
	}

	if (provider.type === "gateway") {
		return [`${baseUrl}/v1`, baseUrl];
	}

	return [baseUrl, `${baseUrl}/v1`];
}

async function fetchJson(url: string, apiKey?: string, options: { method?: "GET" | "POST"; body?: unknown } = {}): Promise<any> {
	const proxied = proxiedProviderRequestUrl(url);
	const headers: Record<string, string> = {
		"x-target-url": proxied.targetBaseUrl,
	};

	if (options.body !== undefined) headers["Content-Type"] = "application/json";
	if (apiKey) {
		headers.Authorization = `Bearer ${apiKey}`;
	}

	const response = await withApiRetry(async () => {
		const result = await fetch(proxied.url, {
			method: options.method ?? "GET",
			headers,
			body: options.body === undefined ? undefined : JSON.stringify(options.body),
		});
		if (!result.ok) {
			const retryAfter = result.headers.get("retry-after");
			throw new Error(`HTTP ${result.status}: ${result.statusText}${retryAfter ? ` retry-after: ${retryAfter}` : ""}`);
		}
		return result;
	});

	const text = await response.text();
	try {
		return JSON.parse(text);
	} catch {
		const snippet = text.trim().slice(0, 120).replace(/\s+/g, " ");
		throw new Error(
			`Expected JSON from ${url} but got ${snippet ? `a non-JSON response ("${snippet}…")` : "an empty response"}. Check the base URL.`,
		);
	}
}

async function discoverOpenAiCompatibleModels(
	provider: KeatingCustomProvider,
): Promise<{ apiBaseUrl: string; models: Model<Api>[] }> {
	const candidateBaseUrls = openAiCompatibleBaseUrls(provider);

	let lastError: unknown;
	let emptyResult: { apiBaseUrl: string; models: Model<Api>[] } | undefined;
	for (const apiBaseUrl of candidateBaseUrls) {
		try {
			const payload = await fetchJson(`${apiBaseUrl}/models`, provider.apiKey);
			const records = Array.isArray(payload?.data) ? payload.data : Array.isArray(payload) ? payload : [];
				const models = records
					.map((record: any): Model<Api> | null => {
					const id = String(record?.id ?? record?.name ?? "").trim();
					if (!id) return null;

					const contextWindow = toContextWindow(
						record?.context_window ?? record?.context_length ?? record?.max_context_length ?? record?.max_model_len,
					);
					const maxTokens = toContextWindow(record?.max_tokens ?? record?.max_output_tokens, contextWindow || 4096);

					return {
						id,
						name: String(record?.display_name ?? record?.name ?? id),
						api: manualProviderApi(provider.type),
						provider: provider.name,
						baseUrl: apiBaseUrl,
						reasoning: inferReasoning(record),
						input: inferInputModes(record),
						cost: modelCost(),
						contextWindow,
						maxTokens,
					};
					})
					.filter((model: Model<Api> | null): model is Model<Api> => model !== null);

			if (models.length > 0) return { apiBaseUrl, models };
			emptyResult ??= { apiBaseUrl, models };
		} catch (error) {
			lastError = error;
		}
	}

	if (emptyResult) return emptyResult;
	throw lastError instanceof Error ? lastError : new Error(`Failed to discover models for ${provider.name}`);
}

async function discoverOllamaModels(baseUrl: string): Promise<Model<Api>[]> {
	const trimmedBaseUrl = trimTrailingSlash(baseUrl);
	const payload = await fetchJson(`${trimmedBaseUrl}/api/tags`);
	const models = Array.isArray(payload?.models) ? payload.models : [];

	const discovered = await Promise.all(
		models.map(async (model: any): Promise<Model<Api> | null> => {
			const details = await fetchJson(`${trimmedBaseUrl}/api/show`, undefined, {
				method: "POST",
				body: { model: model.name },
			});
			const capabilities: string[] = (details as any).capabilities || [];
			if (!capabilities.includes("tools")) return null;

			const modelInfo: any = details.model_info || {};
			const architecture = modelInfo["general.architecture"] || "";
			const contextWindow = toContextWindow(modelInfo[`${architecture}.context_length`], 8192);

			return {
				id: model.name,
				name: model.name,
				api: "openai-completions" as Api,
				provider: "",
				baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
				reasoning: capabilities.includes("thinking"),
				input: ["text"],
				cost: modelCost(),
				contextWindow,
				maxTokens: contextWindow,
			};
		}),
	);

	return discovered.filter((model): model is Model<Api> => model !== null);
}

async function discoverLlamaCppModels(baseUrl: string, apiKey?: string): Promise<Model<Api>[]> {
	const payload = await fetchJson(`${trimTrailingSlash(baseUrl)}/v1/models`, apiKey);
	const records = Array.isArray(payload?.data) ? payload.data : [];

	return records.map((model: any) => {
		const contextWindow = toContextWindow(model?.context_length, 8192);
		return {
			id: String(model.id),
			name: String(model.id),
			api: "openai-completions" as Api,
			provider: "",
			baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
			reasoning: false,
			input: ["text"],
			cost: modelCost(),
			contextWindow,
			maxTokens: toContextWindow(model?.max_tokens, 4096),
		};
	});
}

async function discoverVllmModels(baseUrl: string, apiKey?: string): Promise<Model<Api>[]> {
	const payload = await fetchJson(`${trimTrailingSlash(baseUrl)}/v1/models`, apiKey);
	const records = Array.isArray(payload?.data) ? payload.data : [];

	return records.map((model: any) => {
		const contextWindow = toContextWindow(model?.max_model_len, 8192);
		return {
			id: String(model.id),
			name: String(model.id),
			api: "openai-completions" as Api,
			provider: "",
			baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
			reasoning: false,
			input: ["text"],
			cost: modelCost(),
			contextWindow,
			maxTokens: Math.min(contextWindow, 4096),
		};
	});
}

async function discoverLmStudioModels(baseUrl: string): Promise<Model<Api>[]> {
	const payload = await fetchJson(`${trimTrailingSlash(baseUrl)}/v1/models`);
	const records = Array.isArray(payload?.data) ? payload.data : [];

	return records.map((model: any) => {
		const contextWindow = toContextWindow(model?.context_length ?? model?.max_context_length, 8192);
		return {
			id: String(model?.id),
			name: String(model?.name ?? model?.id),
			api: "openai-completions" as Api,
			provider: "",
			baseUrl: `${trimTrailingSlash(baseUrl)}/v1`,
			reasoning: inferReasoning(model),
			input: inferInputModes(model),
			cost: modelCost(),
			contextWindow,
			maxTokens: toContextWindow(model?.max_tokens, contextWindow),
		};
	});
}

export async function discoverCustomProviderModels(provider: KeatingCustomProvider): Promise<Model<Api>[]> {
	if (AUTO_DISCOVERY_TYPES.has(provider.type)) {
		let models: Model<Api>[];
		switch (provider.type) {
			case "ollama":
				models = await discoverOllamaModels(provider.baseUrl);
				break;
			case "llama.cpp":
				models = await discoverLlamaCppModels(provider.baseUrl, provider.apiKey);
				break;
			case "vllm":
				models = await discoverVllmModels(provider.baseUrl, provider.apiKey);
				break;
			case "lmstudio":
				models = await discoverLmStudioModels(provider.baseUrl);
				break;
			default:
				models = [];
		}

		return models.map((model) => ({ ...model, provider: provider.name }));
	}

	if (OPENAI_COMPATIBLE_TYPES.has(provider.type)) {
		const discovered = await discoverOpenAiCompatibleModels(provider);
		return discovered.models;
	}

	return (provider.models || []).map((model) => ({
		...model,
		provider: provider.name,
		baseUrl: model.baseUrl || provider.baseUrl,
		api: model.api || manualProviderApi(provider.type),
	}));
}

export async function getCustomProviders(): Promise<KeatingCustomProvider[]> {
	return (await getAppStorage().customProviders.getAll()) as KeatingCustomProvider[];
}

export async function syncCustomProviderKeys(): Promise<void> {
	const storage = getAppStorage();
	const providers = await getCustomProviders();

	await Promise.all(
		providers.map(async (provider) => {
			if (provider.apiKey) {
				await storage.providerKeys.set(provider.name, provider.apiKey);
			}
		}),
	);
}

export async function getProviderApiKey(providerName: string): Promise<string | undefined> {
	if (providerName === NOTORGANIC_PROVIDER_ID && isNotOrganicFeatureEnabled()) {
		try {
			await getNotOrganicAccount();
			// Pi's OpenAI-compatible transport expects a non-empty key. This
			// marker never leaves the same-origin route; Nitro replaces it with
			// the server-owned DPoP capability.
			return "notorganic-product-session";
		} catch {
			return undefined;
		}
	}
	const oauthId = providerToOAuthId(providerName);
	if (oauthId) {
		const token = await getOAuthAccessToken(oauthId);
		if (token) return token;
	}

	const storage = getAppStorage();
	const storedKey = await storage.providerKeys.get(providerName);
	if (storedKey) return storedKey;

	const customProviders = await getCustomProviders();
	return customProviders.find((provider) => provider.name === providerName)?.apiKey;
}

const FALLBACK_CHAT_MODEL_IDS: Record<string, string[]> = {
	[NOTORGANIC_PROVIDER_ID]: [NOTORGANIC_DEFAULT_MODEL.id],
	openai: ["gpt-5.5", "gpt-5.5-pro", "gpt-5.4", "gpt-5.3-chat-latest", "gpt-5.2", "gpt-5.1", "gpt-5"],
	anthropic: ["claude-sonnet-4-6", "claude-opus-4-8", "claude-opus-4-7", "claude-sonnet-4-5", "claude-haiku-4-5"],
	google: ["gemini-3.1-pro-preview", "gemini-3.5-flash", "gemini-3-pro-preview", "gemini-2.5-pro"],
};

function providerNeedsKey(provider: string): boolean {
	return provider !== "browser";
}

function preferredModelForProvider(models: Array<Model<Api>>, provider: string): Model<Api> | undefined {
	const providerModels = models.filter((model) => model.provider === provider);
	const ids = FALLBACK_CHAT_MODEL_IDS[provider] ?? [];
	for (const id of ids) {
		const found = providerModels.find((model) => model.id === id);
		if (found) return found;
	}
	return providerModels[0];
}

export async function resolveAvailableChatModel(current: Model<Api>): Promise<Model<Api>> {
	if (!providerNeedsKey(current.provider) || await getProviderApiKey(current.provider)) {
		return current;
	}

	const models = await getSelectableModels();
	for (const provider of [NOTORGANIC_PROVIDER_ID, "openai", "anthropic", "google"]) {
		if (!(await getProviderApiKey(provider))) continue;
		const model = preferredModelForProvider(models, provider);
		if (model) return model;
	}

	return current;
}

export const UNKNOWN_COST = {
	input: 0,
	output: 0,
	cacheRead: 0,
	cacheWrite: 0,
} as const;

export const UNKNOWN_CONTEXT_WINDOW = 8192;
export const UNKNOWN_MAX_TOKENS = 4096;

function keatingCompatibilityModels(filter?: (provider: string) => boolean): Array<Model<Api>> {
	const models: Array<Model<Api>> = [];
	const minimaxModels: Array<[id: string, name: string]> = [
		["MiniMax-M3", "MiniMax-M3"],
		["minimax-m2.7-highspeed", "MiniMax M2.7 Highspeed"],
	];
	const maybeAdd = (provider: string, baseUrl: string) => {
		if (filter && !filter(provider)) return;
		for (const [id, name] of minimaxModels) {
			models.push({
				id,
				name,
				api: "openai-completions" as Api,
				provider,
				baseUrl,
				reasoning: true,
				input: ["text"],
				cost: UNKNOWN_COST,
				contextWindow: 1_000_000,
				maxTokens: 4096,
			});
		}
	};
	maybeAdd("minimax", "https://api.minimax.io/v1");
	maybeAdd("minimax-cn", "https://api.minimaxi.com/v1");
	return models;
}

export async function getSelectableModels(
	filter?: (provider: string) => boolean,
): Promise<Array<Model<Api>>> {
	const models: Array<Model<Api>> = [];

	if (isNotOrganicFeatureEnabled() && (!filter || filter(NOTORGANIC_PROVIDER_ID))) {
		models.push(NOTORGANIC_DEFAULT_MODEL);
	}

	for (const provider of getProviders()) {
		if (!filter || filter(provider)) {
			models.push(...(getModels(provider as any) as Array<Model<Api>>));
		}
	}

	models.push(...keatingCompatibilityModels(filter));

	const customProviders = await getCustomProviders();
	const customModels = await Promise.all(
		customProviders.map(async (provider) => {
			try {
				return await discoverCustomProviderModels(provider);
			} catch (error) {
				console.warn(`Skipping unavailable provider ${provider.name}:`, error);
				return [];
			}
		}),
	);

	models.push(...customModels.flat());
	return models;
}

export function buildSavedModel(saved: any): Model<Api> {
	return {
		id: saved.id,
		name: saved.name,
		api: saved.api as Api,
		provider: saved.provider,
		baseUrl: saved.baseUrl || "",
		reasoning: saved.reasoning,
		input: saved.vision ? (["text", "image"] as Array<"text" | "image">) : (["text"] as Array<"text" | "image">),
		cost: UNKNOWN_COST,
		contextWindow: UNKNOWN_CONTEXT_WINDOW,
		maxTokens: UNKNOWN_MAX_TOKENS,
	};
}

