		(globalThis as { location?: unknown }).location = {
			hostname: "localhost",
			origin: "http://localhost:5173",
		};
		try {
			expect(resolveOAuthRedirectUri("openai-codex")).toBe("http://localhost:1455/auth/callback");
		} finally {
			delete (globalThis as { location?: unknown }).location;
		}
	});

